package com.gestourant.order;
import com.gestourant.restaurant.RestaurantTable; import com.gestourant.user.User; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="orders") public class RestaurantOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="table_id") private RestaurantTable table; @ManyToOne(optional=false) @JoinColumn(name="created_by") private User createdBy; @Enumerated(EnumType.STRING) @Column(nullable=false) private OrderStatus status=OrderStatus.ABIERTA; @Column(nullable=false,precision=12,scale=2) private BigDecimal total=BigDecimal.ZERO; @Column(name="opened_at",nullable=false) private LocalDateTime openedAt=LocalDateTime.now(); @Column(name="closed_at") private LocalDateTime closedAt; @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) private List<OrderItem> items=new ArrayList<>(); protected RestaurantOrder(){} public RestaurantOrder(RestaurantTable t,User u){table=t;createdBy=u;} public Long getId(){return id;} public RestaurantTable getTable(){return table;} public OrderStatus getStatus(){return status;} public BigDecimal getTotal(){return total;} public LocalDateTime getOpenedAt(){return openedAt;} public LocalDateTime getClosedAt(){return closedAt;} public List<OrderItem> getItems(){return items;} public void addItem(OrderItem i){items.add(i);total=total.add(i.getSubtotal());} public void close(){status=OrderStatus.PAGADA;closedAt=LocalDateTime.now();} }
